#!/usr/bin/env python3
"""Group ZMap6 responses by /64 network and classify each as internal or external.

A response is "internal" when the responder address equals the probed
target — the probe came back from the address we aimed at. It is
"external" when a different address responded (typically a CPE,
router, or NAT64 box on a neighboring address).

Aliased /64 prefixes listed in `aliases_file` are skipped, since they
respond to every probe and would pollute the classification.

Output: JSON Lines on stdout, one record per /64 network:

    {"network": "<4 colon groups>", "internal": [...], "external": [...]}

Usage:
    classify-responses.py aliases.txt zmap-output.csv.zst > networks.jsonl
"""
import argparse
import csv
import io
import ipaddress
import json

import zstandard as zstd
from common import COLUMNS,CaptureError,Invalid,decode64
from ledger import parse_record


def stream_csv(path,encoding='zstd',budget=None,logical_records=False):
    with open(path, "rb") as fh:
        reader=(zstd.ZstdDecompressor().stream_reader(fh,read_across_frames=True)
                if encoding=='zstd' else fh)
        bounded=io.BufferedReader(BoundedReader(reader,budget)) if budget is not None else reader
        with io.TextIOWrapper(bounded,encoding='utf-8',newline='') as text:
            if logical_records:
                yield from csv.reader(text,strict=True)
            else:
                for line in text:
                    if line.startswith('saddr'):
                        continue
                    yield line


class BoundedReader(io.RawIOBase):
    def __init__(self,source,budget):
        self.source=source
        self.budget=budget

    def readable(self):
        return True

    def readinto(self,buffer):
        block=self.source.read(min(len(buffer),self.budget[0]+1))
        self.budget[0]-=len(block)
        if self.budget[0]<0:
            raise CaptureError('decompressed byte budget')
        buffer[:len(block)]=block
        return len(block)


def complete_frames(data):
    """Validate complete dictionary-free bounded-window Zstandard framing."""
    at=0
    while at<len(data):
        if at+4>len(data):raise CaptureError('truncated Zstandard magic')
        magic=int.from_bytes(data[at:at+4],'little')
        if 0x184d2a50<=magic<=0x184d2a5f:
            if at+8>len(data):raise CaptureError('truncated skippable frame')
            size=int.from_bytes(data[at+4:at+8],'little');at+=8+size
            if at>len(data):raise CaptureError('truncated skippable frame')
            continue
        if magic!=0xfd2fb528 or at+5>len(data):raise CaptureError('invalid Zstandard frame')
        flag=data[at+4]
        if flag&0x08:raise CaptureError('reserved Zstandard frame bit')
        single=bool(flag&0x20)
        dictionary=(0,1,2,4)[flag&3]
        content=(1 if single else 0,2,4,8)[flag>>6]
        header=5+(not single)+dictionary+content
        if at+header>len(data):raise CaptureError('truncated Zstandard header')
        params=zstd.get_frame_parameters(data[at:at+header])
        if params.dict_id or params.window_size>128*1024**2:
            raise CaptureError('unsupported dictionary or window')
        at+=header
        while True:
            if at+3>len(data):raise CaptureError('truncated Zstandard block')
            block=int.from_bytes(data[at:at+3],'little');at+=3
            kind=(block>>1)&3;size=block>>3
            if kind==3:raise CaptureError('reserved Zstandard block type')
            at+=1 if kind==1 else size
            if at>len(data):raise CaptureError('truncated Zstandard block')
            if block&1:break
        if flag&4:at+=4
        if at>len(data):raise CaptureError('truncated Zstandard checksum')


def capture_records(context,lookup,scratch):
    """Read the actual compressed CSV path with bounded, logical-record parsing."""
    csv.field_size_limit(131072)
    records=[]
    rejected=[]
    decoded=0
    count=0
    budget=[128*1024**2]
    for number,capture in enumerate(context['captures']):
        blocks=[decode64(text,CaptureError) for text in capture['chunks']]
        decoded+=sum(map(len,blocks))
        if decoded>32*1024**2:
            raise CaptureError('decoded byte budget')
        if capture['encoding']=='zstd':
            try:complete_frames(b''.join(blocks))
            except zstd.ZstdError as exc:raise CaptureError('invalid Zstandard header') from exc
        path=scratch/f'capture-{number}.bin'
        with path.open('wb') as output:
            for block in blocks:
                output.write(block)
        del blocks
        try:
            rows=stream_csv(path,capture['encoding'],budget,logical_records=True)
            if next(rows,None)!=list(COLUMNS):
                raise CaptureError('invalid CSV header')
            for ordinal,values in enumerate(rows):
                count+=1
                if count>200000 or any(len(v.encode('utf-8'))>131072 for v in values):
                    raise CaptureError('capture record budget')
                try:
                    row=parse_record(values,context,lookup)
                except (Invalid,ValueError,TypeError):
                    rejected.append([number,ordinal])
                    continue
                records.append(row)
        except (UnicodeError,csv.Error,zstd.ZstdError,EOFError) as exc:
            raise CaptureError('invalid capture encoding') from exc
        finally:
            path.unlink()
    return records,rejected


def record_response(networks,key,target,responder,same_is_internal=True):
    bucket=networks.setdefault(key,{'network':key,'internal':set(),'external':set()})
    if target==responder:
        if not same_is_internal:
            return None
        role='internal'
    else:
        role='external'
    bucket[role].add(responder)
    return role


def classify(records,leases,at,low):
    """TODO: reconcile lease-scoped discovery roles and quarantine state."""
    raise NotImplementedError('campaign classification')


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("aliases_file",
                        help="text file of aliased /64 prefixes (4 colon groups)")
    parser.add_argument("zmap_csv",
                        help="ZMap6 output CSV.zst (saddr,...,responder,...)")
    args = parser.parse_args()

    aliases = set()
    with open(args.aliases_file) as f:
        for line in f:
            aliases.add(line.strip())

    networks: dict[str, dict] = {}
    for row in stream_csv(args.zmap_csv):
        fields = row.split(",")
        if len(fields) < 2:
            continue
        target, responder = fields[0], fields[1]
        try:
            exploded = ipaddress.IPv6Address(target).exploded
        except ipaddress.AddressValueError:
            continue
        net64 = ":".join(exploded.split(":")[:4])
        if net64 in aliases:
            continue
        record_response(networks,net64,target,responder)

    for entry in networks.values():
        entry["internal"] = sorted(entry["internal"])
        entry["external"] = sorted(entry["external"])
        print(json.dumps(entry))


if __name__ == "__main__":
    main()
"""Offline ADB and length-prefixed plist exchange parsing."""
import io
import plistlib
import struct
from xml.parsers.expat import ExpatError


def checksum(data):
    total=0
    for byte in data:
        total=(total+byte)&0xffffffff
    return total


def send_connect():
    command=0x4e584e43
    identity=b'host::zgrab2'
    return struct.pack('<6I',command,0x01000000,4096,len(identity),
                       checksum(identity),command^0xffffffff)+identity


def send_close():
    command=0x45534c43
    return struct.pack('<6I',command,0,0,0,0,command^0xffffffff)


def read_adb_response(data):
    if len(data)<24:
        raise ValueError('short ADB header')
    command,arg0,arg1,length,check,magic=struct.unpack('<6I',data[:24])
    if command^magic!=0xffffffff:
        raise ValueError('bad ADB header')
    if command==0x4e584e43:
        banner=data[24:].decode('utf-8')
        version=f'{(arg0>>16)&255}.{(arg0>>8)&255}.{arg0&255}'
        return ('CNXN',version,banner)
    return ('AUTH',arg0,arg1,data[24:].hex())


GET_VERSION=0
GET_PRODUCT_NAME=1
USBMUXD_COMMANDS={
    GET_VERSION:('ProductVersion','GetValue'),
    GET_PRODUCT_NAME:('ProductName','GetValue')}


def get_value_request(kind):
    key,request=USBMUXD_COMMANDS[kind]
    value=plistlib.dumps({'Key':key,'Label':'usbmuxd','ProtocolVersion':'2',
                         'Request':request},fmt=plistlib.FMT_XML,sort_keys=False)
    return struct.pack('>I',len(value))+value


def get_plists(stream,kind):
    header=stream.read(4)
    size=struct.unpack('>I',header)[0]
    if size==0 or size>65532:
        raise ValueError('invalid plist length')
    body=stream.read(size)
    value=plistlib.loads(body)
    expected=USBMUXD_COMMANDS[kind][0]
    if (type(value) is not dict or set(value)!={'Key','Request','Value'}
            or value['Key']!=expected or value['Request']!='GetValue'
            or type(value['Value']) is not str or not value['Value']):
        raise ValueError('invalid GetValue response')
    return value['Value']


def send_messages(data):
    stream=io.BytesIO(data)
    version=get_plists(stream,GET_VERSION)
    product=get_plists(stream,GET_PRODUCT_NAME)
    if stream.read(1):
        raise ValueError('trailing plist frame')
    return ('sync',version,product)


def signature(kind,data):
    try:
        if kind=='tcp':
            if data:
                raise ValueError('TCP payload must be empty')
            return ('tcp',)
        if kind=='adb':
            return read_adb_response(data)
        return send_messages(data)
    except (ValueError,UnicodeError,OverflowError,TypeError,plistlib.InvalidFileException,ExpatError):
        return None


def probe_script(kind):
    import base64
    encode=lambda b:base64.b64encode(b).decode('ascii')
    if kind=='tcp':
        return [],[]
    if kind=='adb':
        return [encode(send_connect())],[encode(send_close())]
    return [encode(get_value_request(GET_VERSION)),encode(get_value_request(GET_PRODUCT_NAME))],[]

#!/usr/bin/env python3
"""Public sanity cases through bounded child processes and ordinary OS pipes."""
import json,os,signal,subprocess,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent))
from _bounded import CandidateFailure,execute
from bootstrap import install
from _tree import freeze_tree,temporary_tree
from _json_result import check_result


def interrupted(signum,frame):
    for sig in (signal.SIGINT,signal.SIGTERM):signal.signal(sig,signal.SIG_IGN)
    raise KeyboardInterrupt('public check interrupted')


def main():
    if os.geteuid()==0:raise RuntimeError('run the public checker as a nonroot user')
    if len(sys.argv)!=2:raise RuntimeError('usage: python3 public_check.py /workspace/submission')
    for sig in (signal.SIGINT,signal.SIGTERM):signal.signal(sig,interrupted)
    root=Path(__file__).resolve().parent
    scratch=Path(os.environ.get('TMPDIR','/workspace/tmp'));scratch.mkdir(exist_ok=True)
    results=[]
    with temporary_tree(prefix='public-campaign-',dir=scratch) as directory:
        run=Path(directory)
        digest=freeze_tree(Path(sys.argv[1]),run/'submission')
        install(root/'wheels',run/'deps')
        cases=json.loads((root/'examples/fixtures.json').read_text())
        for case in cases:
            with temporary_tree(prefix='case-',dir=run) as work:
                raw=case['raw'].encode() if 'raw' in case else json.dumps(case['input']).encode()
                try:
                    out,err,seconds=execute(run/'submission/campaign.py',raw,Path(work))
                    check_result(out,case['expected'])
                    passed=True
                    reason='correct'
                except (CandidateFailure,ValueError,UnicodeError) as exc:
                    passed=False;seconds=None;reason=str(exc)
                results.append({'name':case['name'],'passed':passed,'seconds':seconds,'reason':reason})
                # A failed public sanity case suffices; never run another full
                # deadline after a candidate has already failed.
                if not passed:break
    passed=len(results)==len(cases) and all(r['passed'] for r in results)
    print(json.dumps({'public_checks_passed':passed,'submission_sha256':digest,'results':results},sort_keys=True))
    return 0 if passed else 1


if __name__=='__main__':
